//! The bridge of Parking.Vehicle, Parking.Car, Parking.Motorcycle: the exports its C# façades
//! call (CodeCoreMorph, D-84). One handle type for the hierarchy; `parking_Vehicle_class` tells
//! the façade which C# class wraps an object that comes back.
use std::ffi::c_char;
use std::sync::Arc;

use super::ccm::{self, ccm_decimal, ccm_status, Handle};
use crate::vehicle::{Vehicle, VehicleKind};

pub struct parking_Vehicle(());

impl Handle for parking_Vehicle {
    type Target = Vehicle;
}

#[unsafe(no_mangle)]
pub extern "C" fn parking_Vehicle_release(handle: *mut parking_Vehicle) {
    ccm::release(handle);
}

#[unsafe(no_mangle)]
pub extern "C" fn parking_Vehicle_key(handle: *const parking_Vehicle) -> u64 {
    ccm::key(handle)
}

/// The class of the object behind a handle, for the façade that wraps it: 1 Car, 2 Motorcycle.
#[unsafe(no_mangle)]
pub extern "C" fn parking_Vehicle_class(self_: *const parking_Vehicle, result: *mut i32) -> ccm_status {
    ccm::guard(|| {
        let class = match ccm::from_handle(self_)?.class() {
            VehicleKind::Car => 1,
            VehicleKind::Motorcycle => 2,
        };
        ccm::put(result, class);
        Ok(())
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn parking_Vehicle_plate(
    self_: *const parking_Vehicle,
    result: *mut *mut c_char,
) -> ccm_status {
    ccm::guard(|| {
        ccm::out_str(result, ccm::from_handle(self_)?.plate());
        Ok(())
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn parking_Vehicle_wheels(self_: *const parking_Vehicle, result: *mut i32) -> ccm_status {
    ccm::guard(|| {
        ccm::put(result, ccm::from_handle(self_)?.wheels());
        Ok(())
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn parking_Vehicle_kind(
    self_: *const parking_Vehicle,
    result: *mut *mut c_char,
) -> ccm_status {
    ccm::guard(|| {
        ccm::out_str(result, ccm::from_handle(self_)?.kind());
        Ok(())
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn parking_Vehicle_size_factor(
    self_: *const parking_Vehicle,
    result: *mut ccm_decimal,
) -> ccm_status {
    ccm::guard(|| {
        ccm::put(result, ccm::dec_out(ccm::from_handle(self_)?.size_factor()));
        Ok(())
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn parking_Vehicle_to_string(
    self_: *const parking_Vehicle,
    result: *mut *mut c_char,
) -> ccm_status {
    ccm::guard(|| {
        ccm::out_str(result, &ccm::from_handle(self_)?.to_string());
        Ok(())
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn parking_Car_new(plate: *const c_char, result: *mut *mut parking_Vehicle) -> ccm_status {
    ccm::guard(|| {
        let car = Vehicle::car(ccm::opt_str(plate).as_deref())?;
        ccm::put(result, ccm::to_handle::<parking_Vehicle>(Arc::new(car)));
        Ok(())
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn parking_Motorcycle_new(
    plate: *const c_char,
    result: *mut *mut parking_Vehicle,
) -> ccm_status {
    ccm::guard(|| {
        let motorcycle = Vehicle::motorcycle(ccm::opt_str(plate).as_deref())?;
        ccm::put(result, ccm::to_handle::<parking_Vehicle>(Arc::new(motorcycle)));
        Ok(())
    })
}

//! The Rust of Parking.Vehicle, Parking.Car, Parking.Motorcycle, ported from C#
//! (CodeCoreMorph, D-84). The C# hierarchy is closed (both subclasses are sealed and came with
//! it), so a vehicle is one type with its kind.
use std::fmt;

use codecoremorph_runtime::{Decimal, Exception, Result};

/// Which vehicle it is: C#'s two sealed subclasses of `Vehicle`.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum VehicleKind {
    Car,
    Motorcycle,
}

/// A vehicle, known by its plate.
#[derive(Debug, PartialEq, Eq)]
pub struct Vehicle {
    plate: String,
    kind: VehicleKind,
}

/// C#'s `ToUpperInvariant`: each character's simple upper case (one character for one; .NET
/// keeps a character whose upper case is longer, such as `ß`).
pub(crate) fn upper_invariant(text: &str) -> String {
    text.chars()
        .map(|c| {
            let mut upper = c.to_uppercase();
            match (upper.next(), upper.next()) {
                (Some(u), None) => u,
                _ => c,
            }
        })
        .collect()
}

impl Vehicle {
    /// C#'s protected constructor: the plate trimmed and in upper case.
    fn new(kind: VehicleKind, plate: Option<&str>) -> Result<Vehicle> {
        let plate = plate.ok_or_else(|| Exception::argument_null("plate"))?.trim();
        if plate.is_empty() {
            return Err(Exception::argument("A plate can't be empty.", "plate"));
        }
        Ok(Vehicle { plate: upper_invariant(plate), kind })
    }

    /// `new Car(plate)`.
    pub fn car(plate: Option<&str>) -> Result<Vehicle> {
        Vehicle::new(VehicleKind::Car, plate)
    }

    /// `new Motorcycle(plate)`.
    pub fn motorcycle(plate: Option<&str>) -> Result<Vehicle> {
        Vehicle::new(VehicleKind::Motorcycle, plate)
    }

    /// The plate, trimmed and in upper case.
    pub fn plate(&self) -> &str {
        &self.plate
    }

    /// The subclass it was in C#.
    pub fn class(&self) -> VehicleKind {
        self.kind
    }

    pub fn wheels(&self) -> i32 {
        match self.kind {
            VehicleKind::Car => 4,
            VehicleKind::Motorcycle => 2,
        }
    }

    pub fn kind(&self) -> &'static str {
        match self.kind {
            VehicleKind::Car => "car",
            VehicleKind::Motorcycle => "motorcycle",
        }
    }

    /// How much of a car's place it takes: fees scale with it.
    pub fn size_factor(&self) -> Decimal {
        match self.kind {
            VehicleKind::Car => Decimal::ONE,
            VehicleKind::Motorcycle => Decimal::new(5, 1),
        }
    }
}

impl fmt::Display for Vehicle {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{} {}", self.kind(), self.plate)
    }
}

