using System;
using System.Globalization;

namespace CodeCoreMorph.Interop
{
    internal static partial class CcmInterop
    {
        // The project's own exceptions the Rust returns, made from the fields its errors
        // carry (their C# constructor's arguments).
        static partial void CreateProjectException(CcmError error, ref Exception result)
        {
            switch (error.Type)
            {
                case "Parking.GarageFullException":
                    result = new Parking.GarageFullException(
                        int.Parse(error.Fields["capacity"], CultureInfo.InvariantCulture));
                    break;
            }
        }
    }
}

