//! The bridge of Parking.Money, a value type: it crosses as its amount (`amount` in,
//! `result_amount` out).
use std::ffi::c_char;

use super::ccm::{self, ccm_decimal, ccm_status};
use crate::money::Money;
use codecoremorph_runtime::Result;

/// A Money from the façade's field, which a constructor checked.
pub(crate) fn money(amount: ccm_decimal) -> Result<Money> {
    Money::new(ccm::dec(amount)?)
}

pub(crate) fn out_money(m: Money, result_amount: *mut ccm_decimal) {
    ccm::put(result_amount, ccm::dec_out(m.amount()));
}

/// new Money(amount): the amount it keeps, or ArgumentOutOfRangeException.
#[unsafe(no_mangle)]
pub extern "C" fn parking_Money_new(amount: ccm_decimal, result_amount: *mut ccm_decimal) -> ccm_status {
