//! The Rust of Parking.Money, ported from C# (CodeCoreMorph, D-84).
use std::any::Any;
use std::collections::hash_map::DefaultHasher;
use std::fmt;
use std::hash::{Hash, Hasher};

use codecoremorph_runtime::{Decimal, Exception, Result};

use crate::limits::CURRENCY;

/// An amount of money in the garage's currency, never negative. `Money::default()` is C#'s
/// `default(Money)`, which is `Money.Zero`.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub struct Money {
    amount: Decimal,
}

impl Money {
    /// `Money.Zero`.
    pub const ZERO: Money = Money { amount: Decimal::ZERO };

    pub fn new(amount: Decimal) -> Result<Money> {
        if amount < Decimal::ZERO {
            return Err(Exception::argument_out_of_range("amount", "Money can't be negative."));
        }
        Ok(Money { amount })
    }

    pub fn amount(&self) -> Decimal {
        self.amount
    }

    /// `a + b`.
    pub fn add(&self, other: Money) -> Result<Money> {
        Money::new(self.amount.checked_add(other.amount)?)
    }

    /// `a * times`.
    pub fn times(&self, times: i32) -> Result<Money> {
        Money::new(self.amount.checked_mul(Decimal::from(times))?)
    }

    /// `a * factor`.
    pub fn scale(&self, factor: Decimal) -> Result<Money> {
        Money::new(self.amount.checked_mul(factor)?)
    }

    /// The smaller of two amounts (the first of equal ones).
    pub fn min(a: Money, b: Money) -> Money {
        if a.amount <= b.amount { a } else { b }
    }

    /// C#'s `Equals(object)`: equal only to a `Money` of the same amount.
    pub fn equals_object(&self, other: &dyn Any) -> bool {
        other.downcast_ref::<Money>().is_some_and(|m| m == self)
    }

    /// C#'s `GetHashCode`: equal amounts hash equally, whatever their scale (not .NET's
    /// numbers).
    pub fn hash_code(&self) -> i32 {
        let mut hasher = DefaultHasher::new();
        self.hash(&mut hasher);
        (hasher.finish() & 0x7fff_ffff) as i32
    }
}

/// The amount in cents, rounded half away from zero, and the currency.
impl fmt::Display for Money {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{} {}", self.amount.to_fixed(2), CURRENCY)
    }
}

