use std::sync::Arc;

use codecoremorph_runtime::{Exception, Result};

use crate::i_rate_plan::RatePlan;
use crate::limits::{MINUTES_PER_DAY, MINUTES_PER_HOUR};
use crate::money::Money;
use crate::vehicle::Vehicle;

/// A fee per started hour, at most a daily cap for each day.
#[derive(Debug)]
pub struct HourlyRate {
    per_hour: Money,
    daily_cap: Money,
}

impl HourlyRate {
    pub fn new(per_hour: Money, daily_cap: Money) -> Result<HourlyRate> {
        if daily_cap.amount() < per_hour.amount() {
            return Err(Exception::argument("The daily cap is less than an hour.", "dailyCap"));
        }
        Ok(HourlyRate { per_hour, daily_cap })
    }

    pub fn per_hour(&self) -> Money {
        self.per_hour
    }

    pub fn daily_cap(&self) -> Money {
        self.daily_cap
    }

    pub fn name(&self) -> String {
        format!("hourly {}", self.per_hour)
    }

    pub fn charge(&self, vehicle: Option<&Arc<Vehicle>>, minutes: i32) -> Result<Money> {
        let vehicle = vehicle.ok_or_else(|| Exception::argument_null("vehicle"))?;
        if minutes < 0 {
            return Err(Exception::argument_out_of_range("minutes", "A stay can't be negative."));
        }
        let days = minutes / MINUTES_PER_DAY;
        let rest = minutes % MINUTES_PER_DAY;
        let hours = (rest + MINUTES_PER_HOUR - 1) / MINUTES_PER_HOUR;
        let total = self.daily_cap.times(days)?.add(Money::min(self.per_hour.times(hours)?, self.daily_cap))?;
        total.scale(vehicle.size_factor())
    }
}

impl RatePlan for HourlyRate {
    fn name(&self) -> Result<String> {
        Ok(HourlyRate::name(self))
    }

    fn charge(&self, vehicle: Option<&Arc<Vehicle>>, minutes: i32) -> Result<Money> {
        HourlyRate::charge(self, vehicle, minutes)
    }
}

