//! The Rust of Parking.Tally<T>, ported from C# (CodeCoreMorph, D-84).
use std::collections::HashMap;
use std::hash::Hash;

use codecoremorph_runtime::{Exception, Result};

/// Counts how often each item was seen. C# enumerated its dictionary in insertion order, which
/// `most_common` depends on, so the counts are kept in the order items were first seen.
#[derive(Debug)]
pub struct Tally<T> {
    counts: Vec<(T, i32)>,
    index: HashMap<T, usize>,
}

impl<T> Default for Tally<T> {
    fn default() -> Self {
        Tally { counts: Vec::new(), index: HashMap::new() }
    }
}

impl<T: Eq + Hash + Clone> Tally<T> {
    pub fn new() -> Tally<T> {
        Tally::default()
    }

    /// C# took a null item for a reference type, which it refused.
    pub fn add(&mut self, item: Option<T>) -> Result<()> {
        let item = item.ok_or_else(|| Exception::argument_null("item"))?;
        match self.index.get(&item) {
            Some(&i) => self.counts[i].1 = self.counts[i].1.wrapping_add(1),
            None => {
                self.index.insert(item.clone(), self.counts.len());
                self.counts.push((item, 1));
            }
        }
        Ok(())
    }

    /// How often the item was seen: 0 for one never seen (and for C#'s null).
    pub fn get(&self, item: Option<&T>) -> i32 {
        item.and_then(|i| self.index.get(i)).map_or(0, |&i| self.counts[i].1)
    }

    /// The number of different items.
    pub fn count(&self) -> i32 {
        i32::try_from(self.counts.len()).unwrap_or(i32::MAX)
    }

    /// The sum of the counts; LINQ's `Sum` is checked, so an overflow is an error.
    pub fn total(&self) -> Result<i32> {
        self.counts.iter().try_fold(0i32, |sum, (_, n)| {
            sum.checked_add(*n)
                .ok_or_else(|| Exception::overflow("Arithmetic operation resulted in an overflow."))
        })
    }

    /// The item seen most often; of those tied, the first one seen.
    pub fn most_common(&self) -> Result<T> {
        let mut best: Option<&(T, i32)> = None;
        for entry in &self.counts {
            if best.is_none_or(|b| entry.1 > b.1) {
                best = Some(entry);
            }
        }
        best.map(|(item, _)| item.clone())
            .ok_or_else(|| Exception::invalid_operation("The tally is empty."))
    }
}

