namespace Parking
{
    /// <summary>Counts how often each item was seen.</summary>
    public sealed class Tally<T>
    {
        // The Rust generic type is exported for the type arguments the project uses: one of these.
        private readonly parking_Tally_intHandle ints;
        private readonly parking_Tally_stringHandle strings;

        public Tally()
        {
            if (typeof(T) == typeof(int))
            {
                CcmInterop.Check(CcmNative.parking_Tally_int_new(out ints));
            }
            else if (typeof(T) == typeof(string))
            {
                CcmInterop.Check(CcmNative.parking_Tally_string_new(out strings));
            }
            else
            {
                throw new NotSupportedException(
                    "Tally<" + typeof(T) + "> has no Rust: the port exports Tally<int> and Tally<string> (CodeCoreMorph, D-84).");
            }
        }

        public void Add(T item)
        {
            if (ints != null)
            {
                CcmInterop.Check(CcmNative.parking_Tally_int_add(ints, (int)(object)item));
            }
            else
            {
                CcmInterop.Check(CcmNative.parking_Tally_string_add(strings, (string)(object)item));
            }
        }

        /// <summary>How often the item was seen: 0 for one never seen.</summary>
        public int this[T item]
        {
            get
            {
                int result;
                if (ints != null)
                {
                    CcmInterop.Check(CcmNative.parking_Tally_int_item(ints, (int)(object)item, out result));
                }
                else
                {
                    CcmInterop.Check(CcmNative.parking_Tally_string_item(strings, (string)(object)item, out result));
                }
                return result;
            }
        }

        /// <summary>The number of different items.</summary>
        public int Count
        {
            get
            {
                int result;
                if (ints != null)
                {
                    CcmInterop.Check(CcmNative.parking_Tally_int_count(ints, out result));
                }
                else
                {
                    CcmInterop.Check(CcmNative.parking_Tally_string_count(strings, out result));
                }
                return result;
            }
        }

        public int Total
        {
            get
            {
                int result;
                if (ints != null)
                {
                    CcmInterop.Check(CcmNative.parking_Tally_int_total(ints, out result));
                }
                else
                {
                    CcmInterop.Check(CcmNative.parking_Tally_string_total(strings, out result));
                }
                return result;
            }
        }

        /// <summary>The item seen most often; of those tied, the first one seen.</summary>
        public T MostCommon()
        {
            if (ints != null)
            {
                int item;
                CcmInterop.Check(CcmNative.parking_Tally_int_most_common(ints, out item));
