//! The Rust of Parking.Garage, ported from C# (CodeCoreMorph, D-84).
use std::collections::HashMap;
use std::fmt;
use std::sync::{Arc, Mutex, MutexGuard, PoisonError};

use codecoremorph_runtime::{Exception, Result};

use crate::garage_full_exception::garage_full;
use crate::i_rate_plan::RatePlan;
use crate::limits::{MAX_CAPACITY, MINUTES_PER_HOUR};
use crate::money::Money;
use crate::tally::Tally;
use crate::vehicle::{upper_invariant, Vehicle};

/// A subscriber to [`Garage::on_vehicle_left`] (C#'s `VehicleLeft` event): the plate and the
/// fee of a vehicle that left.
pub type VehicleLeft = Arc<dyn Fn(&str, Money) -> Result<()> + Send + Sync>;

#[derive(Default)]
struct State {
    parked: Vec<Arc<Vehicle>>,
    entered: HashMap<String, i32>,
    visits: Tally<String>,
    hours: Tally<i32>,
    takings: Money,
}

#[derive(Default)]
struct Subscribers {
    next: i32,
    all: Vec<(i32, VehicleLeft)>,
}

fn lock<T>(m: &Mutex<T>) -> MutexGuard<'_, T> {
    m.lock().unwrap_or_else(PoisonError::into_inner)
}

/// C#'s `Key`: a plate as the garage files it.
fn key(plate: Option<&str>) -> Result<String> {
    let plate = plate.ok_or_else(|| Exception::argument_null("plate"))?;
    Ok(upper_invariant(plate.trim()))
}

/// A garage with a fixed number of places, charging by a rate plan. Its state is behind locks
/// it never holds while it calls out: the plan, a predicate or a subscriber may be C# code
/// that calls back into it.
pub struct Garage {
    capacity: i32,
    plan: Arc<dyn RatePlan>,
    state: Mutex<State>,
    vehicle_left: Mutex<Subscribers>,
}

impl fmt::Debug for Garage {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Garage")
            .field("capacity", &self.capacity)
            .field("count", &self.count())
            .finish_non_exhaustive()
    }
}

impl Garage {
    pub fn new(capacity: i32, plan: Option<Arc<dyn RatePlan>>) -> Result<Garage> {
        if !(1..=MAX_CAPACITY).contains(&capacity) {
            return Err(Exception::argument_out_of_range(
                "capacity",
                format!("A garage has 1 to {MAX_CAPACITY} places."),
            ));
        }
        let plan = plan.ok_or_else(|| Exception::argument_null("plan"))?;
        Ok(Garage {
            capacity,
            plan,
            state: Mutex::default(),
            vehicle_left: Mutex::default(),
        })
    }

    pub fn capacity(&self) -> i32 {
        self.capacity
    }

    pub fn count(&self) -> i32 {
        i32::try_from(lock(&self.state).parked.len()).unwrap_or(i32::MAX)
    }

    pub fn free(&self) -> i32 {
        self.capacity - self.count()
    }

    pub fn takings(&self) -> Money {
        lock(&self.state).takings
    }

    pub fn plan(&self) -> Arc<dyn RatePlan> {
        self.plan.clone()
    }

    /// C#'s indexer: the parked vehicle with this plate.
    pub fn at(&self, plate: Option<&str>) -> Result<Arc<Vehicle>> {
        let key = key(plate)?;
        lock(&self.state)
            .parked
            .iter()
            .find(|v| v.plate() == key)
            .cloned()
            .ok_or_else(|| Exception::key_not_found(format!("No vehicle {key} is parked.")))
    }

    pub fn enter(&self, vehicle: Option<Arc<Vehicle>>, minute: i32) -> Result<()> {
        let vehicle = vehicle.ok_or_else(|| Exception::argument_null("vehicle"))?;
        if minute < 0 {
            return Err(Exception::argument_out_of_range("minute", "Time starts at minute 0."));
        }
        let mut state = lock(&self.state);
        if state.entered.contains_key(vehicle.plate()) {
            return Err(Exception::invalid_operation(format!(
                "{} is parked already.",
                vehicle.plate()
            )));
        }
        if i32::try_from(state.parked.len()).unwrap_or(i32::MAX) == self.capacity {
            return Err(garage_full(self.capacity));
        }
        state.entered.insert(vehicle.plate().to_string(), minute);
        state.visits.add(Some(vehicle.plate().to_string()))?;
        state.hours.add(Some(minute / MINUTES_PER_HOUR % 24))?;
        state.parked.push(vehicle);
        Ok(())
    }

    /// Lets the vehicle out at a minute, charging the plan's fee for its stay.
    pub fn leave(&self, plate: Option<&str>, minute: i32) -> Result<Money> {
        let vehicle = self.at(plate)?;
        let since = lock(&self.state).entered.get(vehicle.plate()).copied().ok_or_else(|| {
            Exception::key_not_found(format!(
                "The given key '{}' was not present in the dictionary.",
                vehicle.plate()
            ))
        })?;
        if minute < since {
            return Err(Exception::argument_out_of_range(
                "minute",
                "A vehicle can't leave before it came.",
            ));
        }
        // The plan may be C#: no lock is held while it charges.
        let fee = self.plan.charge(Some(&vehicle), minute.wrapping_sub(since))?;
        {
            let mut state = lock(&self.state);
            if let Some(i) = state.parked.iter().position(|v| Arc::ptr_eq(v, &vehicle)) {
                state.parked.remove(i);
            }
            state.entered.remove(vehicle.plate());
            state.takings = state.takings.add(fee)?;
        }
        let subscribers: Vec<VehicleLeft> =
            lock(&self.vehicle_left).all.iter().map(|(_, s)| s.clone()).collect();
        for subscriber in subscribers {
            subscriber(vehicle.plate(), fee)?;
        }
        Ok(fee)
    }

    /// How many times a vehicle with this plate came in.
    pub fn visits_of(&self, plate: Option<&str>) -> Result<i32> {
        let key = key(plate)?;
        Ok(lock(&self.state).visits.get(Some(&key)))
    }

    /// The hour of the day in which most vehicles came in.
    pub fn busiest_hour(&self) -> Result<i32> {
        lock(&self.state).hours.most_common()
    }

    /// How many parked vehicles `predicate` takes; C#'s predicate could be null, which it
    /// refused.
    pub fn count_where<F>(&self, predicate: Option<F>) -> Result<i32>
    where
        F: FnMut(&Arc<Vehicle>) -> Result<bool>,
    {
        let mut predicate = predicate.ok_or_else(|| Exception::argument_null("predicate"))?;
        let parked = lock(&self.state).parked.clone();
        let mut count = 0i32;
        for vehicle in &parked {
            if predicate(vehicle)? {
                count = count
                    .checked_add(1)
                    .ok_or_else(|| Exception::overflow("Arithmetic operation resulted in an overflow."))?;
            }
        }
        Ok(count)
    }

    /// The parked vehicles' plates, in ordinal order.
    pub fn plates(&self) -> Vec<String> {
        let mut plates: Vec<String> =
            lock(&self.state).parked.iter().map(|v| v.plate().to_string()).collect();
        plates.sort();
        plates
    }

    /// C#'s `VehicleLeft += subscriber`: a token to unsubscribe with.
    pub fn on_vehicle_left(&self, subscriber: VehicleLeft) -> i32 {
        let mut subscribers = lock(&self.vehicle_left);
        let token = subscribers.next;
        subscribers.next = subscribers.next.wrapping_add(1);
        subscribers.all.push((token, subscriber));
        token
    }

    /// C#'s `VehicleLeft -= subscriber`.
    pub fn remove_vehicle_left(&self, token: i32) {
        lock(&self.vehicle_left).all.retain(|(t, _)| *t != token);
    }
}

