using System;
using System.Collections.Generic;
using CodeCoreMorph.Interop;

namespace Parking
{
    /// <summary>A garage with a fixed number of places, charging by a rate plan.</summary>
    public sealed class Garage
    {
        private static readonly parking_Garage_vehicle_left_fn VehicleLeftThunk = OnVehicleLeft;

        internal readonly parking_GarageHandle Handle;

        // Keeps the façade of a Rust plan alive, so Plan gives the same object back.
        private readonly IRatePlan plan;
        private readonly object gate = new object();
        private Action<string, Money> vehicleLeft;
        private int vehicleLeftToken = -1;

        public Garage(int capacity, IRatePlan plan)
        {
            parking_GarageHandle handle;
            using (parking_IRatePlanHandle planHandle = IRatePlanBridge.HandleOf(plan))
            {
                CcmInterop.Check(CcmNative.parking_Garage_new(capacity, planHandle, out handle));
            }
            Handle = handle;
            this.plan = plan;
            CcmObjects.Register(handle.Key, this);
        }

        /// <summary>Raised after a vehicle left, with its plate and its fee.</summary>
        public event Action<string, Money> VehicleLeft
        {
            add
            {
                lock (gate)
                {
                    if (value == null)
                    {
                        return;
                    }
                    if (vehicleLeft == null)
                    {
                        CcmInterop.Check(CcmNative.parking_Garage_subscribe_vehicle_left(
                            Handle, CcmInterop.Pin(this), CcmInterop.Release, VehicleLeftThunk, out vehicleLeftToken));
                    }
                    vehicleLeft += value;
                }
            }
            remove
            {
                lock (gate)
                {
                    vehicleLeft -= value;
                    if (vehicleLeft == null && vehicleLeftToken >= 0)
                    {
                        CcmInterop.Check(CcmNative.parking_Garage_unsubscribe_vehicle_left(Handle, vehicleLeftToken));
                        vehicleLeftToken = -1;
                    }
                }
            }
        }

        public int Capacity
        {
            get
            {
                int result;
                CcmInterop.Check(CcmNative.parking_Garage_capacity(Handle, out result));
                return result;
            }
        }

        public int Count
        {
            get
            {
                int result;
                CcmInterop.Check(CcmNative.parking_Garage_count(Handle, out result));
                return result;
            }
        }

        public int Free
        {
            get
            {
                int result;
                CcmInterop.Check(CcmNative.parking_Garage_free(Handle, out result));
                return result;
            }
        }

        public Money Takings
        {
            get
            {
                CcmDecimal result;
                CcmInterop.Check(CcmNative.parking_Garage_takings(Handle, out result));
                return Money.FromNative(result);
            }
        }

        public IRatePlan Plan
        {
            get
            {
                parking_IRatePlanHandle result;
                CcmInterop.Check(CcmNative.parking_Garage_plan(Handle, out result));
                return IRatePlanBridge.FromHandle(result);
            }
        }

        /// <summary>The parked vehicle with this plate.</summary>
        public Vehicle this[string plate]
        {
            get
            {
                parking_VehicleHandle result;
                CcmInterop.Check(CcmNative.parking_Garage_item(Handle, plate, out result));
                return Vehicle.FromHandle(result);
            }
        }

        public void Enter(Vehicle vehicle, int minute)
        {
            CcmInterop.Check(CcmNative.parking_Garage_enter(Handle, Vehicle.HandleOf(vehicle), minute));
        }

        /// <summary>Lets the vehicle out at a minute, charging the plan's fee for its stay.</summary>
        public Money Leave(string plate, int minute)
        {
            CcmDecimal result;
            CcmInterop.Check(CcmNative.parking_Garage_leave(Handle, plate, minute, out result));
            return Money.FromNative(result);
        }

        /// <summary>How many times a vehicle with this plate came in.</summary>
        public int VisitsOf(string plate)
        {
            int result;
            CcmInterop.Check(CcmNative.parking_Garage_visits_of(Handle, plate, out result));
            return result;
        }

        /// <summary>The hour of the day in which most vehicles came in.</summary>
        public int BusiestHour()
        {
            int result;
            CcmInterop.Check(CcmNative.parking_Garage_busiest_hour(Handle, out result));
            return result;
        }

        public int CountWhere(Func<Vehicle, bool> predicate)
        {
            parking_Garage_count_where_fn call = null;
            if (predicate != null)
            {
                call = (IntPtr context, IntPtr vehicle, out bool result) =>
                {
                    var vehicleHandle = new parking_VehicleHandle(vehicle);
                    return CcmInterop.Callback(() => predicate(Vehicle.FromHandle(vehicleHandle)), out result);
                };
            }
            int count;
            CcmInterop.Check(CcmNative.parking_Garage_count_where(Handle, IntPtr.Zero, call, out count));
            GC.KeepAlive(call);
            return count;
        }

        /// <summary>The parked vehicles' plates, in ordinal order.</summary>
        public IList<string> Plates()
        {
            int count;
            CcmInterop.Check(CcmNative.parking_Garage_plates_count(Handle, out count));
            var plates = new List<string>(count);
            for (int i = 0; i < count; i++)
            {
                IntPtr plate;
                CcmInterop.Check(CcmNative.parking_Garage_plates_at(Handle, i, out plate));
                plates.Add(CcmInterop.TakeString(plate));
            }
            return plates;
        }

        internal static parking_GarageHandle HandleOf(Garage garage)
        {
            return garage == null ? parking_GarageHandle.Null : garage.Handle;
        }

        private static int OnVehicleLeft(IntPtr context, IntPtr plate, CcmDecimal fee_amount)
        {
            string key = CcmInterop.Utf8(plate);
            Money fee = Money.FromNative(fee_amount);
            return CcmInterop.Callback(() =>
            {
                Action<string, Money> handler = CcmInterop.Target<Garage>(context).vehicleLeft;
                if (handler != null)
                {
                    handler(key, fee);
                }
            });
        }
    }
