//! The Rust of Parking.Shift, ported from C# (CodeCoreMorph, D-84).
use std::fmt;
use std::sync::{Arc, Mutex, MutexGuard, PoisonError};

use codecoremorph_runtime::{Exception, Result};

use crate::garage::Garage;
use crate::money::Money;

#[derive(Default)]
struct Counts {
    takings: Money,
    departures: i32,
}

fn lock<T>(m: &Mutex<T>) -> MutexGuard<'_, T> {
    m.lock().unwrap_or_else(PoisonError::into_inner)
}

/// Adds up a garage's departures until it is disposed (or dropped: C#'s `IDisposable`).
pub struct Shift {
    garage: Arc<Garage>,
    tally: Arc<Mutex<Counts>>,
    token: Mutex<Option<i32>>,
}

impl fmt::Debug for Shift {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Shift")
            .field("departures", &self.departures())
            .field("open", &self.is_open())
            .finish_non_exhaustive()
    }
}

impl Shift {
    pub fn new(garage: Option<Arc<Garage>>) -> Result<Shift> {
        let garage = garage.ok_or_else(|| Exception::argument_null("garage"))?;
        let tally: Arc<Mutex<Counts>> = Arc::default();
        let seen = tally.clone();
        let token = garage.on_vehicle_left(Arc::new(move |_plate, fee| {
            let mut tally = lock(&seen);
            tally.takings = tally.takings.add(fee)?;
            tally.departures = tally.departures.wrapping_add(1);
            Ok(())
        }));
        Ok(Shift { garage, tally, token: Mutex::new(Some(token)) })
    }

    pub fn takings(&self) -> Money {
        lock(&self.tally).takings
    }

    pub fn departures(&self) -> i32 {
        lock(&self.tally).departures
    }

    pub fn is_open(&self) -> bool {
        lock(&self.token).is_some()
    }

    /// Ends the shift's subscription; again, nothing.
    pub fn dispose(&self) {
        if let Some(token) = lock(&self.token).take() {
            self.garage.remove_vehicle_left(token);
        }
    }
}

impl Drop for Shift {
    fn drop(&mut self) {
        self.dispose();
    }
}

