//! The program Parking.Cli, ported from C# (CodeCoreMorph, D-84). `parking_cli_main` is its
//! `Main`, given the arguments without the program's name, returning the exit code.
//!
//! Parking.Cli KIND:PLATE:MINUTES...: parks each vehicle at minute 0, lets each leave after its
//! minutes on the hourly plan, and prints each fee and the takings.
use std::sync::Arc;

use codecoremorph_runtime::{Decimal, Exception, Result};

use crate::garage::Garage;
use crate::garage_full_exception::GARAGE_FULL;
use crate::hourly_rate::HourlyRate;
use crate::limits::MAX_CAPACITY;
use crate::money::Money;
use crate::vehicle::Vehicle;

/// What C#'s `int.TryParse(text, NumberStyles.None, CultureInfo.InvariantCulture, ...)`
/// takes: digits only, no sign or space, within an `int`.
fn minutes(text: &str) -> Option<i32> {
    if text.is_empty() || !text.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    text.parse().ok()
}

/// What the C# `Main` caught: `ArgumentException` and `InvalidOperationException`, and the
/// types that derive from them.
fn caught(e: &Exception) -> bool {
    [
        "System.ArgumentException",
        "System.ArgumentNullException",
        "System.ArgumentOutOfRangeException",
        "System.InvalidOperationException",
        "System.ObjectDisposedException",
        GARAGE_FULL,
    ]
    .iter()
    .any(|t| e.is(t))
}

fn make(kind: &str, plate: &str) -> Result<Option<Vehicle>> {
    match kind {
        "car" => Vehicle::car(Some(plate)).map(Some),
        "motorcycle" => Vehicle::motorcycle(Some(plate)).map(Some),
        _ => Ok(None),
    }
}

/// The run between `try` and `catch`: an exit code it chose, or the error it threw.
fn run(args: &[String], garage: &Garage) -> Result<Option<i32>> {
    let mut stays: Vec<(String, i32)> = Vec::new();
    for arg in args {
        let parts: Vec<&str> = arg.split(':').collect();
        let stay = if parts.len() == 3 { minutes(parts[2]) } else { None };
        let Some(stay) = stay else {
            eprintln!("not KIND:PLATE:MINUTES: {arg}");
            return Ok(Some(2));
        };
        let Some(vehicle) = make(parts[0], parts[1])? else {
            eprintln!("no such kind of vehicle: {}", parts[0]);
            return Ok(Some(2));
        };
        let vehicle = Arc::new(vehicle);
        garage.enter(Some(vehicle.clone()), 0)?;
        stays.push((vehicle.plate().to_string(), stay));
    }
    for (plate, stay) in &stays {
        let fee = garage.leave(Some(plate), *stay)?;
        println!("{plate} paid {fee}");
    }
    Ok(None)
}

pub fn parking_cli_main(args: &[String]) -> i32 {
    if args.is_empty() {
        eprintln!("usage: Parking.Cli KIND:PLATE:MINUTES...");
        return 2;
    }
    let plan = Money::new(Decimal::new(250, 2))
        .and_then(|per_hour| Ok((per_hour, Money::new(Decimal::from(20))?)))
        .and_then(|(per_hour, cap)| HourlyRate::new(per_hour, cap));
    let garage = plan.and_then(|plan| Garage::new(MAX_CAPACITY, Some(Arc::new(plan))));
    let garage = match garage {
        Ok(garage) => garage,
        Err(e) => {
            eprintln!("Unhandled exception. {}: {e}", e.dotnet_type());
            return 134;
        }
    };
    match run(args, &garage) {
        Ok(Some(code)) => code,
        Ok(None) => {
            println!("takings {}", garage.takings());
            0
        }
        Err(e) if caught(&e) => {
            eprintln!("{e}");
            1
        }
        Err(e) => {
            eprintln!("Unhandled exception. {}: {e}", e.dotnet_type());
            134
        }
    }
}

