/// A rate plan that charges one fee and remembers what it was asked.
struct RecordingPlan {
    fee: Money,
    vehicles: Mutex<Vec<Option<Arc<Vehicle>>>>,
    minutes: Mutex<Vec<i32>>,
    /// When set, what charge returns.
    failure: Option<Exception>,
}

impl RecordingPlan {
    fn new(fee: Money) -> RecordingPlan {
        RecordingPlan { fee, vehicles: Mutex::default(), minutes: Mutex::default(), failure: None }
    }
}

impl RatePlan for RecordingPlan {
    fn name(&self) -> Result<String> {
        Ok("recording".to_string())
    }

    fn charge(&self, vehicle: Option<&Arc<Vehicle>>, minutes: i32) -> Result<Money> {
        if let Some(failure) = &self.failure {
            return Err(failure.clone());
        }
        self.vehicles.lock().unwrap().push(vehicle.cloned());
        self.minutes.lock().unwrap().push(minutes);
        Ok(self.fee)
    }
}

